from __future__ import annotations

import argparse
import json
import statistics
from collections import defaultdict
from pathlib import Path
from typing import Any, Callable


def load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text())


def fmt(value: float, digits: int = 2) -> str:
    return f"{value:.{digits}f}"


def speedup(baseline_ms: float, optimized_ms: float) -> float:
    return baseline_ms / optimized_ms


def group_records(
    records: list[dict[str, Any]],
    shape_key: str,
) -> dict[tuple[int, ...], dict[str, dict[str, Any]]]:
    grouped: dict[tuple[int, ...], dict[str, dict[str, Any]]] = defaultdict(dict)
    for record in records:
        shape = tuple(record[shape_key])
        grouped[shape][record["implementation"]] = record
    return grouped


